import numpy as np

TARGET_COUNT = 2007
max_n = 15
results = {}

def calculate_count(S, n):
    """Calculates the number of triples (x, y, z) in S^3 such that x+y+z is divisible by n."""
    count = 0
    for x in S:
        for y in S:
            for z in S:
                if (x + y + z) % n == 0:
                    count += 1
    return count

print(f"Starting investigation for n up to {max_n}...")

for n in range(1, max_n + 1):
    results[n] = {}

    # Iterate over all possible split points k: R = {1, ..., k}, B = {k+1, ..., n}
    # k=0 means R is empty, k=n means B is empty.
    for k in range(n + 1):
        R = list(range(1, k + 1))
        B = list(range(k + 1, n + 1))

        # Calculate N_R
        N_R = calculate_count(R, n)

        # Calculate N_B
        N_B = calculate_count(B, n)

        N_total = N_R + N_B

        results[n][k] = N_total

        if N_total == TARGET_COUNT:
            print(f"\nFound a solution! n={n}, k={k}. Total count = {N_total}")
            break # Stop investigating this n if found
        elif n <= 10 and k % 2 == 0: # Print some intermediate results for visibility
             print(f"n={n}, k={k}, Count={N_total}")

print("\n--- Summary of results up to n=15 ---")
for n in range(1, max_n + 1):
    summary = []
    for k in range(n + 1):
        count = results[n][k]
        summary.append(f"k={k}: {count}")
    results[n]['summary'] = ", ".join(summary)
    print(f"N={n}: {results[n]['summary']}")

# Check if any solution was found
found = False
for n in range(1, max_n + 1):
    for k in range(n + 1):
        if results[n][k] == TARGET_COUNT:
            found = True
            print(f"\nSuccess: The smallest n found is n={n} with k={k}.")
            break
    if found:
        break

if not found:
    print("\nNo solution found for n <= 15 with the specified coloring scheme.")

def check_sum(n, r):
    b = n - r
    if r > 0 and b > 0:
        return r**3 + b**3
    return None

# Search for solutions up to n=50 (since 50^2 = 2500 > 2007)
target = 2007
solutions = []
for n in range(2, 51):
    # We only need to check r up to n/2 due to symmetry
    for r in range(1, n // 2 + 1):
        result = check_sum(n, r)
        if result == target:
            solutions.append((n, r, n - r))
            break # Found solution for this n

print(f"Solutions found for r^3 + (n-r)^3 = 2007: {solutions}")
